'use strict';
const $=id=>document.getElementById(id);
const species=[
 {file:'sunflower',name:'Girasol',message:'Te mereces todas las flores del mundo y quiero ser yo quien te las dé siempre.'},
 {file:'rose',name:'Rosa',message:'Si las flores hablaran, te dirían lo que yo no alcanzo a decirte.'},
 {file:'lily',name:'Lirio',message:'Eres mi excusa favorita para creer en los detalles, porque si tú fueras primavera, yo aprendería a florecer cada tarde.'},
 {file:'hydrangea',name:'Hortensia',message:'No me importa cuánto tiempo tome, yo solo quiero que seas tú, que solo seamos nosotros.'},
 {file:'dahlia',name:'Dalia',message:'No necesito una fecha para recordarte cuánto te quiero.'},
 {file:'jasmine',name:'Jazmín',message:'Si parece imposible alcanzar una estrella, yo lo haría por ti.'},
 {file:'chrysanthemum',name:'Crisantemo',message:'Te amo con toda mi alma, mi niña hermosa y peleona.'},
 {file:'forgetmenot',name:'Nomeolvides',message:'Si la vida me dejara escoger un lugar bonito para quedarme, yo escogería estar a tu lado.'},
 {file:'magnolia',name:'Magnolia',message:'No sé cómo regalarte el mundo entero, pero sí cómo quererte un poquito más cada día.'},
 {file:'gerbera',name:'Gerbera',message:'Si hoy pudiera pedirle algo a la vida, le pediría verte sonreír y tener la suerte de ser una de tus razones.'}
];
const music=$('music');let musicWanted=false;music.volume=.45;
$('music-toggle').addEventListener('click',async()=>{if(music.paused){try{await music.play();musicWanted=true;$('music-toggle').textContent='♫ Pausar música';$('music-toggle').setAttribute('aria-pressed','true');}catch{$('music-toggle').textContent='♫ Toca para escuchar';}}else{music.pause();musicWanted=false;$('music-toggle').textContent='♫ Activar música';$('music-toggle').setAttribute('aria-pressed','false');}});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const canvas=$('flower-canvas'),ctx=canvas.getContext('2d'),video=$('intro-video'),seen=new Set();
let scene='animation-scene',assets=[],assetPromise,particles=[],elapsed=0,lastFrame=0,paused=false,frame=0,animationStarted=false,width=0,height=0,lastCaption='',openIndex=-1;
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
const ease=t=>{t=clamp(t);return t*t*(3-2*t);};
function showScene(id){for(const node of document.querySelectorAll('.scene'))node.hidden=node.id!==id;scene=id;window.scrollTo({top:0,behavior:'instant'});const heading=$(id).querySelector('[tabindex="-1"]');if(heading)heading.focus({preventScroll:true});}
function recolor(image){const raw=document.createElement('canvas');raw.width=image.naturalWidth;raw.height=image.naturalHeight;const rc=raw.getContext('2d',{willReadFrequently:true});rc.drawImage(image,0,0);const data=rc.getImageData(0,0,raw.width,raw.height);let minX=raw.width,minY=raw.height,maxX=0,maxY=0;for(let y=0;y<raw.height;y+=2)for(let x=0;x<raw.width;x+=2){if(data.data[(y*raw.width+x)*4+3]>30){minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);}}
 const yellow=document.createElement('canvas');yellow.width=320;yellow.height=320;const yc=yellow.getContext('2d');const bw=Math.max(1,maxX-minX+8),bh=Math.max(1,maxY-minY+8),scale=290/Math.max(bw,bh);yc.drawImage(raw,Math.max(0,minX-4),Math.max(0,minY-4),bw,bh,(320-bw*scale)/2,(320-bh*scale)/2,bw*scale,bh*scale);
 const pink=document.createElement('canvas');pink.width=320;pink.height=320;const pc=pink.getContext('2d');pc.drawImage(yellow,0,0);const pixels=pc.getImageData(0,0,320,320),d=pixels.data;
 for(let i=0;i<d.length;i+=4){const r=d[i]/255,g=d[i+1]/255,b=d[i+2]/255;if(d[i+3]<2)continue;const yellowMask=clamp((r-g*.93)*15)*clamp((g-b-.025)*7);if(yellowMask>.001){const light=clamp(.2+(.2126*r+.7152*g+.0722*b)*.72,.3,.95),chroma=(1-Math.abs(2*light-1))*.61,m=light-chroma/2;const target=[m+chroma,m,m+chroma*.36];d[i]=255*(r*(1-yellowMask)+target[0]*yellowMask);d[i+1]=255*(g*(1-yellowMask)+target[1]*yellowMask);d[i+2]=255*(b*(1-yellowMask)+target[2]*yellowMask);}}
 pc.putImageData(pixels,0,0);return {yellow,pink,url:pink.toDataURL('image/png')};
}
async function loadAssets(){const results=await Promise.allSettled(species.map(s=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{try{resolve(recolor(im));}catch(e){reject(e);}};im.onerror=()=>reject(new Error(s.file));im.src=`assets/${s.file}.png`;})));assets=results.map(r=>r.status==='fulfilled'?r.value:null);const ok=assets.every(Boolean);$('asset-error').hidden=ok;if(ok){buildGarden();updateCover();}return ok;}
function updateCover(){$('final-bouquet').replaceChildren(...[3,4,1].map(i=>{const img=new Image();img.src=assets[i].url;img.alt='';return img;}));}
function buildGarden(){const grid=$('flower-grid');grid.replaceChildren();species.forEach((s,i)=>{const button=document.createElement('button');button.type='button';button.className='flower-button';button.id=`flower-${i}`;button.style.setProperty('--tilt',`${(i%3-1)*5}deg`);button.setAttribute('aria-label',`${s.name}: abrir mi mensaje`);const image=new Image();image.src=assets[i].url;image.alt='';const name=document.createElement('span');name.className='flower-label';name.textContent=s.name;button.append(image,name);button.addEventListener('click',()=>openFlower(i));grid.append(button);});updateProgress();}
function updateProgress(){const count=seen.size;$('progress').textContent=`${count} de 10 mensajes descubiertos`;for(let i=0;i<10;i++){const b=$(`flower-${i}`);if(b){b.classList.toggle('picked',seen.has(i));b.disabled=seen.has(i);b.setAttribute('aria-label',`${species[i].name}: ${seen.has(i)?'mensaje leído':'abrir mi mensaje'}`);}}$('last-hint').textContent=count===10?'Y todavía tengo algo más para ti…':'Una sorpresa te espera al final.';}
function openFlower(i){if(seen.has(i))return;openIndex=i;$('message-flower').src=assets[i].url;$('message-name').textContent=`${species[i].name} · para ti`;$('message-text').textContent=species[i].message;$('message-dialog').showModal();}
function closeMessage(){$('message-dialog').close();}
$('close-message').addEventListener('click',closeMessage);$('keep-message').addEventListener('click',closeMessage);$('message-dialog').addEventListener('click',e=>{if(e.target===$('message-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeMessage();}});
let flyingCount=0,ending=false;
$('message-dialog').addEventListener('close',()=>{if(openIndex<0||seen.has(openIndex))return;const i=openIndex,button=$(`flower-${i}`),rect=button.getBoundingClientRect();seen.add(i);const flying=new Image();flying.src=assets[i].url;flying.className='flying-flower';flying.alt='';flying.setAttribute('aria-hidden','true');flying.style.cssText=`left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;--fly-x:${i%2?'-35vw':'35vw'};`;document.body.append(flying);flyingCount++;updateProgress();setTimeout(()=>{flying.remove();flyingCount--;if(seen.size===10&&flyingCount===0&&!ending){ending=true;setTimeout(()=>{$('garden-scene').classList.add('leaving');setTimeout(()=>{$('garden-scene').classList.remove('leaving');showScene('final-scene');ending=false;},reduced.matches?0:700);},450);}},reduced.matches?100:1800);const next=species.findIndex((_,n)=>!seen.has(n));if(next>=0)$(`flower-${next}`).focus({preventScroll:true});});
video.addEventListener('error',()=>{$('video-error').hidden=false;});video.addEventListener('ended',showGarden);$('to-flowers').addEventListener('click',showGarden);
async function showGarden(){video.pause();const ok=await assetPromise;if(!ok){$('asset-error').hidden=false;return;}showScene('garden-scene');updateProgress();}
function seeded(n){const t=Math.sin(n*127.1+311.7)*43758.5453;return t-Math.floor(t);}
function layoutParticles(){const box=canvas.getBoundingClientRect();width=Math.max(280,box.width);height=box.height;const ratio=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*ratio);canvas.height=Math.round(height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);const mask=document.createElement('canvas');mask.width=Math.round(width);mask.height=Math.round(height);const mc=mask.getContext('2d',{willReadFrequently:true});mc.fillStyle='#000';mc.textAlign='center';mc.textBaseline='middle';const mobile=width<620;const lines=mobile?['Karen,','te amo','mucho']:['Karen,','te amo mucho'];const maxTextWidth=width*.88;let fontSize=mobile?width*.225:Math.min(140,width*.14);mc.font=`bold ${fontSize}px Georgia`;let max=Math.max(...lines.map(t=>mc.measureText(t).width));if(max>maxTextWidth)fontSize*=maxTextWidth/max;mc.font=`bold ${fontSize}px Georgia`;const lineHeight=fontSize*1.16;const startY=(height-(lines.length-1)*lineHeight)/2;lines.forEach((line,i)=>mc.fillText(line,width/2,startY+i*lineHeight));const pixels=mc.getImageData(0,0,mask.width,mask.height).data;const step=mobile?7:9;particles=[];let i=0;for(let y=0;y<height;y+=step)for(let x=0;x<width;x+=step){if(pixels[(Math.floor(y)*mask.width+Math.floor(x))*4+3]>110){particles.push({x,y,sx:seeded(i+1)*width,sy:seeded(i+2000)*height,type:i%10,delay:seeded(i+700)*1.3,rotation:(seeded(i+30)-.5)*1.2,scale:step*(1.7+seeded(i+40)*.4),phase:seeded(i+12)*6.28});i++;}}
}
function drawFlower(asset,x,y,size,rotation,pinkAmount,opacity=1){if(!asset||opacity<=0)return;ctx.save();ctx.translate(x,y);ctx.rotate(rotation);ctx.globalAlpha=opacity;ctx.drawImage(asset.yellow,-size/2,-size/2,size,size);if(pinkAmount>0){ctx.globalAlpha=opacity*pinkAmount;ctx.drawImage(asset.pink,-size/2,-size/2,size,size);}ctx.restore();}
function caption(title,subtitle){if(lastCaption===title)return;lastCaption=title;$('animation-title').textContent=title;$('animation-caption').textContent=subtitle;$('animation-description').textContent=title+' '+subtitle;}
function drawAnimation(t){ctx.clearRect(0,0,width,height);if(t<6)caption('Karen, este jardín es para ti.','Un poquito de amarillo, un poquito de amor.');else if(t<13)caption('Lo bonito también se transforma.','De amarillo a rosa, de flores a palabras.');else if(t<20)caption('Hay algo que quiero decirte…','Karen, te amo mucho.');else caption('Tengo una cosita para ti…','Mira lo que viene ahora.');const gather=ease((t-8)/6),scatter=ease((t-19.5)/3);for(let i=0;i<particles.length;i++){const p=particles[i];const appear=ease((t-p.delay)/2);const color=ease((t-3.8-p.delay)/4);let x=p.sx+(p.x-p.sx)*gather,y=p.sy+(p.y-p.sy)*gather;const sway=(1-gather)*Math.sin(t*.7+p.phase)*9;const burst=seeded(i+99)*6.28;x+=Math.cos(burst)*scatter*width*.65+sway;y+=Math.sin(burst)*scatter*height*.65;const opacity=appear*(1-scatter)*(.4+.6*gather);drawFlower(assets[p.type],x,y,p.scale*(.8+.2*gather),p.rotation*(1-gather),color,opacity);}
 // Large sprigs introduce each variety before the small blossoms form the lettering.
 const bigFade=1-ease((t-7)/5);for(let i=0;i<10;i++){const col=i%5,row=Math.floor(i/5),x=width*(.1+col*.2),y=height*(.27+row*.48)+Math.sin(t*.8+i)*7;const size=Math.min(width/5*1.1,height*.38);drawFlower(assets[i],x,y,size,(seeded(i+34)-.5)*.45,ease((t-3.5-i*.16)/4),ease((t-i*.18)/2)*bigFade);}}
function tick(now){const dt=lastFrame?Math.min(now-lastFrame,60):0;lastFrame=now;if(!paused&&!document.hidden)elapsed+=dt/1000;drawAnimation(elapsed);if(elapsed>=23){finishAnimation();return;}frame=requestAnimationFrame(tick);}
async function startAnimation(){if(animationStarted)return;animationStarted=true;video.pause();showScene('animation-scene');$('animation-title').textContent='Tu jardín está floreciendo…';$('animation-caption').textContent='Un momento, estoy preparando tus flores.';const ok=await assetPromise;if(!ok){animationStarted=false;return;}if(scene!=='animation-scene')return;elapsed=reduced.matches?15:0;paused=reduced.matches;lastFrame=0;lastCaption='';$('pause-animation').textContent=paused?'Continuar':'Pausar';layoutParticles();cancelAnimationFrame(frame);frame=requestAnimationFrame(tick);}
async function finishAnimation(){cancelAnimationFrame(frame);showScene('video-scene');video.currentTime=0;video.muted=true;try{await video.play();}catch{$('video-error').hidden=false;$('video-error').textContent='Toca el botón de reproducción para ver tu video.';}}
$('skip-animation').addEventListener('click',finishAnimation);$('pause-animation').addEventListener('click',()=>{paused=!paused;$('pause-animation').textContent=paused?'Continuar':'Pausar';if(!paused&&elapsed>=23)finishAnimation();});
$('back-garden').addEventListener('click',()=>{seen.clear();updateProgress();showScene('garden-scene');});
$('replay').addEventListener('click',()=>{cancelAnimationFrame(frame);seen.clear();updateProgress();animationStarted=false;elapsed=0;lastCaption='';startAnimation();});
$('retry-assets').addEventListener('click',async()=>{$('retry-assets').disabled=true;assetPromise=loadAssets();const ok=await assetPromise;$('retry-assets').disabled=false;if(ok&&scene==='animation-scene'){animationStarted=false;startAnimation();}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(scene==='animation-scene'){layoutParticles();drawAnimation(elapsed);}},150);});document.addEventListener('visibilitychange',()=>{lastFrame=0;if(document.hidden){video.pause();music.pause();}else if(musicWanted){music.play().catch(()=>{});}});reduced.addEventListener('change',e=>{if(e.matches&&scene==='animation-scene'){elapsed=15;paused=true;$('pause-animation').textContent='Continuar';}});
assetPromise=loadAssets();
startAnimation();
